//! Piece-square feature tests: literal cross-language golden vectors,
//! exhaustive index coverage, perspective/mirror symmetry, metadata exclusion,
//! incremental delta parity and oversized structurally-valid positions.
//!
//! Golden vectors were produced by an independent Python FEN-to-index encoder
//! using only the documented schema formula, then embedded here as literals.
//! They are not generated by `horseflight::eval::features`.

mod common;

use common::{mirror_fen, position};

use horseflight::eval::features::{
    apply_change, extract, extract_into, piece_feature_index, revert_change, FeatureVector,
    FEATURE_DIMENSION, PERSPECTIVES, ROLES, SCHEMA_ID, SCHEMA_VERSION,
};
use horseflight::{Color, Position, Role, Square};

const FIXTURES: [&str; 7] = [
    "rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1",
    "r1bq1r2/ppp3pp/2n1k3/3pP3/3P4/2P2N2/PP3PPP/R2QKB1R b KQ - 2 11",
    "r3k2r/p1ppqpb1/bn2pnp1/3PN3/1p2P3/2N2Q1p/PPPBBPPP/R3K2R w KQkq - 0 1",
    "r3k2r/8/8/8/8/8/8/R3K2R w KQkq - 0 1",
    "4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1",
    "n1r1k3/1P6/8/8/8/8/8/4K3 w - - 0 1",
    "4k3/1P6/8/8/8/8/1P6/4K3 w - - 0 1",
];

/// Start position, white perspective.
const START_WHITE: &[usize] = &[
    8, 9, 10, 11, 12, 13, 14, 15, 65, 70, 130, 133, 192, 199, 259, 324, 432, 433, 434, 435, 436,
    437, 438, 439, 505, 510, 570, 573, 632, 639, 699, 764,
];

/// Asymmetric middlegame, white perspective.
const MIDDLEGAME_WHITE: &[usize] = &[
    8, 9, 13, 14, 15, 18, 27, 36, 85, 133, 192, 199, 259, 324, 419, 432, 433, 434, 438, 439, 490,
    570, 632, 637, 699, 748,
];

/// The same asymmetric middlegame, black perspective (rank-flipped).
const MIDDLEGAME_BLACK: &[usize] = &[
    8, 9, 10, 14, 15, 27, 82, 130, 192, 197, 259, 340, 412, 419, 426, 432, 433, 437, 438, 439, 493,
    573, 632, 639, 699, 764,
];

/// En passant position, black perspective.
const EN_PASSANT_BLACK: &[usize] = &[27, 324, 412, 764];

/// Promotion position, white perspective.
const PROMOTION_WHITE: &[usize] = &[49, 324, 504, 634, 764];

fn set_indices(features: &FeatureVector) -> Vec<usize> {
    features
        .iter()
        .enumerate()
        .filter_map(|(index, value)| (*value == 1.0).then_some(index))
        .collect()
}

fn piece_count(position: &Position) -> usize {
    position.board().squares().iter().flatten().count()
}

#[test]
fn schema_metadata_and_dimension_are_fixed() {
    assert_eq!(SCHEMA_ID, "horseflight-piece-square");
    assert_eq!(SCHEMA_VERSION, 1);
    assert_eq!(FEATURE_DIMENSION, 768);
    assert_eq!(PERSPECTIVES, [Color::White, Color::Black]);
    assert_eq!(ROLES, Role::ALL);
}

#[test]
fn literal_cross_language_golden_vectors_match() {
    let cases = [
        (FIXTURES[0], Color::White, START_WHITE),
        (FIXTURES[1], Color::White, MIDDLEGAME_WHITE),
        (FIXTURES[1], Color::Black, MIDDLEGAME_BLACK),
        (FIXTURES[4], Color::Black, EN_PASSANT_BLACK),
        (FIXTURES[5], Color::White, PROMOTION_WHITE),
    ];
    for (fen, perspective, expected) in cases {
        let features = extract(&position(fen), perspective);
        assert_eq!(set_indices(&features), expected, "{fen} as {perspective:?}");
    }
}

#[test]
fn every_perspective_index_is_in_range_and_unique() {
    for perspective in PERSPECTIVES {
        let mut seen = vec![false; FEATURE_DIMENSION];
        for piece_color in Color::ALL {
            for role in ROLES {
                for index in 0..64 {
                    let square = Square::from_index(index);
                    let feature = piece_feature_index(piece_color, role, square, perspective);
                    assert!(feature < FEATURE_DIMENSION);
                    assert!(!seen[feature], "duplicate feature index {feature}");
                    seen[feature] = true;
                }
            }
        }
        assert!(
            seen.iter().all(|present| *present),
            "not all inputs are reachable"
        );
    }
}

#[test]
fn extraction_is_binary_and_matches_the_piece_multiset() {
    for fen in FIXTURES {
        let position = position(fen);
        for perspective in PERSPECTIVES {
            let features = extract(&position, perspective);
            assert_eq!(features.len(), FEATURE_DIMENSION);
            assert!(features.iter().all(|value| *value == 0.0 || *value == 1.0));
            assert_eq!(
                features.iter().filter(|value| **value == 1.0).count(),
                piece_count(&position),
                "{fen} as {perspective:?}"
            );
            let mut reused = [1.0; FEATURE_DIMENSION];
            extract_into(&position, perspective, &mut reused);
            assert_eq!(reused, features);
        }
    }
}

#[test]
fn extraction_does_not_assume_at_most_32_pieces() {
    // Structurally valid FEN (one king per side) with 48 pieces.
    let fen = "QQQQKQQQ/QQQQQQQQ/QQQQQQQQ/QQQQQQQQ/8/8/qqqqqqqq/qqqqkqqq w - - 0 1";
    let position = position(fen);
    assert!(piece_count(&position) > 32);
    for perspective in PERSPECTIVES {
        let features = extract(&position, perspective);
        assert_eq!(
            features.iter().filter(|value| **value == 1.0).count(),
            piece_count(&position)
        );
    }
}

#[test]
fn perspective_and_colour_mirroring_preserve_the_encoded_relation() {
    for fen in FIXTURES {
        let original = position(fen);
        let mirrored = position(&mirror_fen(fen));
        assert_eq!(
            extract(&original, Color::White),
            extract(&mirrored, Color::Black),
            "{fen} white perspective"
        );
        assert_eq!(
            extract(&original, Color::Black),
            extract(&mirrored, Color::White),
            "{fen} black perspective"
        );
    }
}

#[test]
fn side_to_move_castling_en_passant_and_clocks_are_excluded() {
    let same_placement = [
        "4k3/8/8/8/8/8/8/4K2R w K - 0 1",
        "4k3/8/8/8/8/8/8/4K2R b - - 17 42",
        "4k3/8/8/8/8/8/8/4K2R w - - 3 9",
    ];
    let en_passant = [
        "4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1",
        "4k3/8/8/3pP3/8/8/8/4K3 w - - 9 40",
    ];
    for group in [&same_placement[..], &en_passant[..]] {
        let first = position(group[0]);
        for fen in &group[1..] {
            for perspective in PERSPECTIVES {
                assert_eq!(
                    extract(&first, perspective),
                    extract(&position(fen), perspective),
                    "{fen} as {perspective:?}"
                );
            }
        }
    }
}

fn assert_delta_parity(position: &Position) {
    for perspective in PERSPECTIVES {
        for movement in position.legal_moves().iter().copied() {
            let mut trial = *position;
            let before = extract(&trial, perspective);
            let undo = trial
                .play(movement)
                .unwrap_or_else(|error| panic!("{} failed: {error}", movement.to_uci()));
            let after = extract(&trial, perspective);

            let mut forward = before;
            for change in undo.piece_changes() {
                apply_change(&mut forward, perspective, change);
            }
            assert_eq!(
                forward,
                after,
                "forward delta {} as {perspective:?} in {}",
                movement.to_uci(),
                position.to_fen()
            );

            let mut reverse = forward;
            for change in undo.piece_changes().iter().rev() {
                revert_change(&mut reverse, perspective, change);
            }
            assert_eq!(
                reverse,
                before,
                "reverse delta {} as {perspective:?} in {}",
                movement.to_uci(),
                position.to_fen()
            );

            trial.unmake(&undo).expect("LIFO unmake");
            assert_eq!(trial, *position);
        }
    }
}

#[test]
fn incremental_deltas_match_full_rebuild_for_every_legal_move() {
    for fen in FIXTURES {
        assert_delta_parity(&position(fen));
    }
}

#[test]
fn all_promotion_roles_and_capture_promotions_parity_full_rebuild() {
    let quiet = position("4k3/1P6/8/8/8/8/1P6/4K3 w - - 0 1");
    let mut roles = Vec::new();
    for movement in quiet.legal_moves().iter().copied() {
        if let Some(role) = movement.promotion_role() {
            roles.push(role);
        }
    }
    roles.sort_by_key(|role| role.index());
    roles.dedup();
    assert_eq!(roles, Role::PROMOTION_TARGETS, "all promotion roles appear");
    assert_delta_parity(&quiet);
    assert_delta_parity(&position("n1r1k3/1P6/8/8/8/8/8/4K3 w - - 0 1"));
}
